     "text": "דמי מנוי בהתחייבות לשנה - 89.99EURO שזה בערך ₪320 לשנה<br>מקבלים<br>תמונות, ווקטורים, מוקאפים של פוטושופ, חבילות אייקונים והורדות ללא הגבלה<br>יש גם דמי מנוי חודשי בסך 9.99EURO.<br>האתר השני הכי משתלם הוא",
