     "type": "p",
     "text": "אנשים שואלים אותי: \"מה צריך להגיש ללקוח בסיום עבודה של עיצוב לוגו?\" אז הינה דוגמה למייל ששלחתי ללקוח עם תיאור של כל החומרים המצורפים. חשוב לציין!!! אסור בשום פנים ואופן להעביר פונטים ללקוח. אלה אם!!!! אלה פונטים חינמיים כמו מהפרוייקט של fonts.google.com אז הם מותרים לשימוש מסחרי ושיתוף. לי אישית אין בעיה למסור קובץ AI סופי הרי גם ככה אני משתח את האפקטים ולא משאיר אותם \"חיים\" אז זה כמו להגיש PDF."
